import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it. Clean open ground in the lower middle where the character will stand; horizon at about 60 % of the height."
TWO = "Two DIFFERENT poses of the same character side by side with a wide gap between them, both full body, bold clean thick outlines. "
P = {
 'hero': ("2:3", "Full body, side view facing to the right, leaning forward and pulling hard: a thick brown rope goes over the shoulder on the LEFT side of the image and both hands grip it in front of the chest, determined happy face: eyebrows lowered, a big confident grin, feet planted. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + " " + KEY()),
 'shock_tired': ("3:2", TWO + "LEFT copy: facing the viewer, shocked: eyebrows tilted up in the middle, wide eyes, mouth wide open in an O, both hands pressed against the sides of the head. RIGHT copy: facing the viewer, exhausted: hunched forward, arms hanging down limp, droopy half-closed eyes, eyebrows tilted up in the middle, mouth open with the pink tongue hanging out. Whole bodies in frame with a margin. " + CHAR + " " + KEY()),
 'glass_strain': ("3:2", TWO + "LEFT copy: facing the viewer, disappointed: holding an empty clear drinking glass upside down in one hand and looking at it, sad droopy eyebrows, small frown. RIGHT copy: side view facing to the LEFT, leaning far back with the whole body tilted to the right, both arms stretched forward to the left with both fists closed as if pulling a rope in a tug of war (no rope drawn), eyes squeezed shut, teeth clenched. Whole bodies in frame with a margin. " + CHAR + " " + KEY()),
 'tug': ("3:2", "One small cute cartoon tugboat seen exactly from the side, facing to the right: a red hull with a black rubber tyre bumper strip along the side, a white cabin with three round windows, a short black funnel with a red stripe, a flat open back deck on the left. No people, no water, no rope. Bold clean thick outlines. " + OBJ + " Nothing green on the object. " + KEY()),
 'iceberg': ("2:3", "One whole iceberg seen from the side as a single object, including the part that would be under water: on top a small jagged snowy white peak, and below it a huge much wider rounded bulk of pale blue ice about six times bigger than the peak, tapering to a rounded bottom. Simple big shapes, white and pale-blue flat colours with one soft shade. No water, no face. Bold clean thick outlines. " + OBJ + " " + KEY('magenta')),
 'city': ("3:2", "A small hot desert city skyline seen from the sea, on a strip of pale yellow sand: a cluster of five tall modern glass skyscrapers in light blue and grey, one very tall slim needle-shaped tower in the middle much taller than the others, two small palm trees, low sand dunes on both sides. Bold clean thick outlines. " + OBJ + " " + KEY('magenta')),
 'bg': ("2:3", "A calm open ocean seen from sea level, vertical picture: a clear warm light-blue sky with two small flat white clouds in the top 55 % of the picture, a straight horizon line at 55 % of the height, and a flat calm medium-blue sea filling the lower 45 % with a few simple light wave lines. No sun, no land, no boats, no objects. " + BG.replace(" Clean open ground in the lower middle where the character will stand; horizon at about 60 % of the height.", "")),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# iceberg-tow - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
print('ok')
